# config/deploy.rb — generated by RailsVPS Studio
lock "~> 3.19"

set :application, "beautiful"
set :repo_url, "git@github.com:hongan94/Beautiful.git"
set :branch, ENV.fetch("BRANCH", "main")
set :deploy_to, "/home/deploy/Beautiful"
set :keep_releases, 5

# Ruby on the server (rbenv of the "deploy" user)
set :rbenv_type, :user
set :rbenv_ruby, "3.2.6"

# Files & folders shared between releases (live in /home/deploy/Beautiful/shared)
append :linked_files, ".env"
append :linked_dirs, "log", "tmp/pids", "tmp/cache", "tmp/sockets", "public/system", "public/uploads", "storage", "vendor/bundle", "node_modules"

# db:prepare = create database if missing, then migrate
set :migration_role, :db
set :migration_command, "db:prepare"

# Load shared/.env for rake/rails commands (assets:precompile, db:prepare, ...)
namespace :rvs do
  task :load_env do
    env_prefix = "set -a; [ -f #{shared_path}/.env ] && . #{shared_path}/.env; set +a;"
    %i[rake rails].each { |cmd| SSHKit.config.command_map.prefix[cmd].unshift(env_prefix) }
  end
end
after "rbenv:map_bins", "rvs:load_env"

# Puma runs as a systemd service (created by RailsVPS Studio → "Chuẩn bị server")
set :puma_service, "beautiful_puma"
namespace :puma do
  %w[start stop restart status].each do |command|
    desc "#{command} Puma (systemd)"
    task command do
      on roles(:app) do
        execute :sudo, "-n", :systemctl, command, fetch(:puma_service)
      end
    end
  end
end
after "deploy:published", "puma:restart"

set :sidekiq_service, "beautiful_sidekiq"
namespace :sidekiq do
  %w[start stop restart status].each do |command|
    desc "#{command} Sidekiq (systemd)"
    task command do
      on roles(:app) do
        execute :sudo, "-n", :systemctl, command, fetch(:sidekiq_service)
      end
    end
  end
end
after "deploy:published", "sidekiq:restart"
